{"path":"services.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Programs & Cohorts — {{BUSINESS_NAME}}</title>
  <meta name='description' content='Small cohort programs and focused tracks for steady lifestyle changes.'>
  <style>
    :root{--bg:#fbfbfb;--card:#ffffff;--ink:#0f1724;--muted:#6b7280;--accent:#6b5ce7;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:var(--ink);background:var(--bg)}
    .wrap{max-width:980px;margin:36px auto;padding:28px}
    header{display:flex;align-items:center;justify-content:space-between;gap:16px}
    .brand{display:flex;flex-direction:column}
    .brand h1{margin:0;font-size:18px;letter-spacing:0.4px}
    nav{display:flex;gap:12px;flex-wrap:wrap}
    nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
    nav a[href$='services.html']{color:var(--ink);font-weight:600}
    .hero{margin-top:20px;background:linear-gradient(180deg,#fff 0%,#fcfbff 100%);padding:22px;border-radius:14px;box-shadow:0 6px 24px rgba(17,17,24,0.04);display:flex;gap:18px}
    .hero .lead{flex:1}
    .pill{display:inline-block;background:var(--accent);color:white;padding:6px 10px;border-radius:999px;font-size:13px}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:18px;margin-top:18px}
    .card{background:var(--card);border-radius:12px;padding:16px;box-shadow:0 6px 18px rgba(11,12,17,0.03)}
    .track{border-left:4px solid var(--accent);padding-left:12px;margin-bottom:12px}
    .muted{color:var(--muted);font-size:13px}
    .cta{display:inline-block;background:var(--accent);color:#fff;padding:10px 14px;border-radius:10px;text-decoration:none}

    /* subtle SVG background via data URL */
    body::before{content:'';position:fixed;inset:0;z-index:-1;opacity:0.06;background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='400' height='400' viewBox='0 0 400 400'><defs><pattern id='p' width='80' height='80' patternUnits='userSpaceOnUse'><rect width='80' height='80' fill='none'/><path d='M0 20 Q20 0 40 20 T80 20' stroke='%236b5ce7' stroke-opacity='0.15' fill='none' stroke-width='2'/></pattern></defs><rect width='100%25' height='100%25' fill='url(%23p)'/></svg>");background-repeat:repeat}

    /* session planner styles */
    .widget h3{margin:0 0 8px 0}
    .sessions{display:flex;flex-direction:column;gap:8px}
    .session-row{display:flex;gap:8px;align-items:center}
    .session-row input[type='text']{flex:1;padding:8px;border-radius:8px;border:1px solid #e6e7ee}
    .session-row select{padding:8px;border-radius:8px;border:1px solid #e6e7ee}
    button.small{padding:8px 10px;border-radius:8px;border:0;background:#eef2ff;color:var(--accent);cursor:pointer}
    pre.output{white-space:pre-wrap;background:#0f1724;color:#e6eefb;padding:12px;border-radius:8px;margin-top:10px}
    .copy{margin-top:8px;background:#0f1724;color:#fff;border:0;padding:8px 12px;border-radius:8px;cursor:pointer}

    footer{margin-top:28px;font-size:13px;color:var(--muted);display:flex;justify-content:space-between}
    @media(max-width:880px){.grid{grid-template-columns:1fr}nav{display:none}}
  </style>
</head>
<body>
  <div class='wrap'>
    <header>
      <div class='brand'>
        <h1>{{BUSINESS_NAME}}</h1>
        <div class='muted'>Care through learning cohorts — thoughtful, evidence-aware guidance</div>
      </div>
      <nav>
        <a href='index.html'>Studio</a>
        <a href='services.html'>Programs</a>
        <a href='conditions.html'>Concerns</a>
        <a href='approach.html'>Method</a>
        <a href='pricing.html'>Rates</a>
        <a href='about.html'>About</a>
        <a href='book.html'>Reserve</a>
        <a href='contact.html'>Say Hello</a>
      </nav>
    </header>

    <section class='hero'>
      <div class='lead'>
        <span class='pill'>Cohort model</span>
        <h2 style='margin-top:12px;margin-bottom:6px'>Group rhythms and focused tracks for practical change</h2>
        <p class='muted'>Join small cohorts that balance clinical perspectives with everyday practices. Tracks are eight weeks with intentional peer support and a clinician guide.</p>
        <p style='margin-top:12px'><a class='cta' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a></p>
      </div>
      <div style='width:320px;display:flex;flex-direction:column;gap:12px'>
        <div class='card'>
          <strong>Upcoming cohort</strong>
          <div class='muted' style='margin-top:6px'>Roots Track — begins next month · limited to 12 participants</div>
          <div style='margin-top:10px;display:flex;gap:8px'><a class='cta' href='book.html'>Reserve a spot</a><a href='contact.html' style='padding:10px;border-radius:8px;text-decoration:none;background:#f3f4f6;color:var(--muted)'>Ask a question</a></div>
        </div>
        <div class='card'>
          <strong>Pricing note</strong>
          <div class='muted' style='margin-top:6px'>Programs are priced per person; sliding scales considered. Not a substitute for emergency care.</div>
        </div>
      </div>
    </section>

    <div class='grid'>
      <main>
        <div class='card'>
          <h3 style='margin-top:0'>Offerings tuned to life</h3>
          <p class='muted'>Each cohort blends short teaching sessions, small-group coaching and practical assignments. You’ll leave with a plan you can actually use — and peers who help you keep it.</p>

          <div style='margin-top:12px'>
            <div class='track'>
              <strong>Seasons Cohort — 8-week group</strong>
              <div class='muted'>Coursework + fortnightly group consults. Focus: long-term rhythm, sleep, stress resilience.</div>
              <div style='margin-top:8px'>Investment: sliding scale available; typical range $320–$720.</div>
            </div>

            <div class='track'>
              <strong>Roots Track — Practitioner-led small group</strong>
              <div class='muted'>Deep dive into nutrition, movement, and scaffolded skills. Peer accountability included.</div>
              <div style='margin-top:8px'>Investment: cohort fee with payment plans; scholarships offered.</div>
            </div>

            <div class='track'>
              <strong>Reset Mini — 4-week focused series</strong>
              <div class='muted'>Short, targeted cycles to address a single priority (sleep, gut health, energy).</div>
              <div style='margin-top:8px'>Investment: smaller group pricing for targeted wins.</div>
            </div>
          </div>
        </div>

        <div class='card' style='margin-top:14px'>
          <h3 style='margin-top:0'>Session Planner</h3>
          <p class='muted'>Build a personalized short plan for your next 4 meetings — useful whether you prefer one-on-one or a cohort path.</p>
          <div class='widget'>
            <div class='sessions' id='sessions'>
              <div class='session-row'>
                <input type='text' placeholder='Focus (e.g., sleep habits)' class='s-title' value='Initial assessment'>
                <select class='s-type'><option>Intake</option><option>Coaching</option><option>Practice review</option><option>Follow-up</option></select>
                <button class='small' onclick='removeRow(event)'>−</button>
              </div>
            </div>
            <div style='margin-top:8px;display:flex;gap:8px'>
              <button class='small' onclick='addRow()'>+ Add session</button>
              <button class='small' onclick='generatePlan()'>Draft plan</button>
            </div>
            <pre class='output' id='planOutput' aria-live='polite'>Your planner summary will appear here.</pre>
            <button class='copy' onclick='copyText("planOutput")'>Copy plan</button>
          </div>
        </div>

        <div class='card' style='margin-top:14px'>
          <h3 style='margin-top:0'>Whole-person inventory</h3>
          <p class='muted'>Tick the areas you'd like help with. We create a suggested consultation agenda and a follow-up cadence you can bring to your first session.</p>
          <form id='inventory'>
            <label><input type='checkbox' name='area' value='Sleep'/> Sleep</label><br>
            <label><input type='checkbox' name='area' value='Nutrition'/> Nutrition</label><br>
            <label><input type='checkbox' name='area' value='Movement'/> Movement & energy</label><br>
            <label><input type='checkbox' name='area' value='Stress'/> Stress & mood</label><br>
            <label><input type='checkbox' name='area' value='Digestive'/> Digestive health</label><br>
            <label><input type='checkbox' name='area' value='Women''s health'/> Women's health</label><br>
            <label><input type='checkbox' name='area' value='Chronic pain'/> Chronic pain</label><br>
            <div style='margin-top:10px'>
              <button type='button' class='small' onclick='generateAgenda()'>Create agenda & cadence</button>
            </div>
          </form>
          <pre class='output' id='agendaOutput'>Selected areas will generate a consultation agenda and suggested follow-up cadence.</pre>
          <button class='copy' onclick='copyText("agendaOutput")'>Copy agenda</button>
        </div>

      </main>

      <aside>
        <div class='card'>
          <strong>Why this model?</strong>
          <p class='muted' style='margin-top:8px'>Cohorts multiply learning: short teaching, shared practice, and guided reflection. Not a substitute for emergency or specialized medical care.</p>
        </div>

        <div class='card' style='margin-top:12px'>
          <strong>Book a chat</strong>
          <div class='muted' style='margin-top:8px'>Two-week hold for cohort placement. Call {{PHONE}} or <a href='mailto:{{EMAIL}}'>email</a>.</div>
          <div style='margin-top:12px'><a class='cta' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a></div>
        </div>
      </aside>
    </div>

    <footer>
      <div>Serving {{CITY}}, {{STATE}}</div>
      <div class='muted'>Not medical advice. Educational and supportive care resources.</div>
    </footer>
  </div>

  <script>
    function addRow(){
      const container = document.getElementById('sessions');
      const div = document.createElement('div');
      div.className = 'session-row';
      div.innerHTML = "<input type='text' placeholder='Focus (e.g., sleep habits)' class='s-title'/>"+
                      "<select class='s-type'><option>Intake</option><option>Coaching</option><option>Practice review</option><option>Follow-up</option></select>"+
                      "<button class='small' onclick='removeRow(event)'>−</button>";
      container.appendChild(div);
    }
    function removeRow(e){
      const btn = e.currentTarget || e.target;
      const row = btn.closest('.session-row');
      if(row) row.remove();
    }
    function generatePlan(){
      const rows = Array.from(document.querySelectorAll('.session-row'));
      if(rows.length===0){document.getElementById('planOutput').textContent='No sessions defined.';return}
      const lines = rows.map((r,i)=>{
        const title = r.querySelector('.s-title').value || ('Session '+(i+1));
        const type = r.querySelector('.s-type').value;
        return (i+1)+'. '+title+' — '+type;
      });
      const summary = 'Personal session plan (draft):\n' + lines.join('\n') + '\n\nBring this to your first meeting to focus check-ins and early practices.';
      document.getElementById('planOutput').textContent = summary;
    }
    function generateAgenda(){
      const checked = Array.from(document.querySelectorAll('#inventory input[name="area"]:checked')).map(i=>i.value);
      if(checked.length===0){document.getElementById('agendaOutput').textContent='No areas selected.';return}
      const agenda = [];
      agenda.push('Consultation agenda (60 min):');
      agenda.push('- 0–10 min: Presenting concerns & goals');
      agenda.push('- 10–25 min: Focused review — ' + checked[0]);
      if(checked.length>1) agenda.push('- 25–40 min: Secondary areas — ' + checked.slice(1).join(', '));
      agenda.push('- 40–50 min: Practical interventions & immediate steps');
      agenda.push('- 50–60 min: Wrap-up, measures, and cohort resources');
      agenda.push('\nSuggested follow-up cadence:');
      agenda.push('- Short check-in (15 min) at 1–2 weeks');
      agenda.push('- Focused follow-up (30–45 min) at 6 weeks');
      agenda.push('- Group reflection or cohort touchpoint at week 8');
      document.getElementById('agendaOutput').textContent = agenda.join('\n');
    }
    function copyText(id){
      const txt = document.getElementById(id).textContent;
      if(!txt) return;
      if(navigator.clipboard && navigator.clipboard.writeText){
        navigator.clipboard.writeText(txt).then(()=>alert('Copied to clipboard'));
      }else{
        const ta = document.createElement('textarea');ta.value=txt;document.body.appendChild(ta);ta.select();try{document.execCommand('copy');alert('Copied to clipboard')}catch(e){alert('Copy failed')};ta.remove();
      }
    }
  </script>
</body>
</html>"} 
{"path":"conditions.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Concerns we support — {{BUSINESS_NAME}}</title>
  <meta name='description' content='A compassionate guide to common concerns and how we approach them in cohort or individual pathways.'>
  <style>
    :root{--bg:#ffffff;--card:#fff;--ink:#0b1220;--muted:#555;--accent:#0b8a6b}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,#fff,#fbfcff);margin:0;color:var(--ink)}
    .site{max-width:920px;margin:28px auto;padding:20px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{color:var(--muted);text-decoration:none;margin-left:10px}
    .hero{padding:18px;background:rgba(11,138,107,0.06);border-radius:12px;margin-top:14px}
    .columns{display:grid;grid-template-columns:1fr 320px;gap:16px;margin-top:16px}
    .card{background:var(--card);padding:14px;border-radius:12px;box-shadow:0 12px 30px rgba(11,18,25,0.03)}
    .muted{color:var(--muted)}
    .tag{display:inline-block;background:var(--accent);color:#fff;padding:6px 10px;border-radius:20px}
    ul.concerns{padding-left:18px}
    footer{margin-top:18px;font-size:13px;color:var(--muted)}
  </style>
</head>
<body>
  <div class='site'>
    <header>
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <div class='muted'>Thoughtful, integrative group and individual support</div>
      </div>
      <nav>
        <a href='index.html'>Studio</a>
        <a href='services.html'>Programs</a>
        <a href='conditions.html'>Concerns</a>
        <a href='approach.html'>Method</a>
        <a href='pricing.html'>Rates</a>
        <a href='book.html'>Reserve</a>
      </nav>
    </header>

    <section class='hero'>
      <div style='display:flex;justify-content:space-between;align-items:center'>
        <div>
          <h2 style='margin:0'>Concerns we commonly work with</h2>
          <div class='muted' style='margin-top:6px'>We frame support as a learning and change process; not a promise of cure.</div>
        </div>
        <div class='tag'>Supportive guidance</div>
      </div>
    </section>

    <div class='columns'>
      <main>
        <div class='card'>
          <h3 style='margin-top:0'>Typical areas</h3>
          <p class='muted'>Our approach is educational and exploratory. We help people build sustainable routines and interpret evidence relevant to their lives. Not every path suits every person; clinical decisions are individualized.</p>
          <ul class='concerns'>
            <li><strong>Sleep disturbances</strong> — habit, environment, circadian patterns</li>
            <li><strong>Low energy & fatigue</strong> — lifestyle, pacing, nutritional patterns</li>
            <li><strong>Digestive complaints</strong> — dietary patterns, routines, symptom tracking</li>
            <li><strong>Pain & movement</strong> — pacing, movement prescription, recovery habits</li>
            <li><strong>Mood & stress</strong> — regulation practices, structure, rest cycles</li>
            <li><strong>Women's health</strong> — cycle awareness, lifestyle interactions</li>
          </ul>

          <h4 style='margin-top:12px'>What we do and do not do</h4>
          <p class='muted'>We provide educational assessment, collaborative planning, and cohort-supported behavior change. We do not provide emergency services, guarantee cure, or replace specialist medical care when needed.</p>

          <div style='margin-top:12px'>
            <strong>Typical path</strong>
            <ol class='muted'>
              <li>Initial consult to map priorities (60 min)</li>
              <li>Actionable practices + cohort learning</li>
              <li>Check-ins and measure review (individual or group)</li>
            </ol>
          </div>
        </div>

        <div class='card' style='margin-top:14px'>
          <h3 style='margin-top:0'>Session Planner & Inventory</h3>
          <p class='muted'>Quick tools to prepare for a consult — generate an agenda and follow-up cadence you can bring to the first meeting.</p>

          <div>
            <label class='muted' style='font-weight:600'>Pick your areas</label>
            <form id='condInventory' style='margin-top:8px'>
              <label><input type='checkbox' name='area' value='Sleep'/> Sleep</label><br>
              <label><input type='checkbox' name='area' value='Pain'/> Pain & movement</label><br>
              <label><input type='checkbox' name='area' value='Energy'/> Energy</label><br>
              <label><input type='checkbox' name='area' value='Digestive'/> Digestive</label><br>
            </form>
            <div style='margin-top:8px'>
              <button onclick='generateCondAgenda()' class='small-btn'>Create agenda</button>
            </div>
            <pre id='condOutput' style='background:#081622;color:#dff3ea;padding:12px;border-radius:8px;margin-top:10px'>No agenda yet.</pre>
            <button onclick='copyOut("condOutput")' style='margin-top:8px;padding:8px 10px;border-radius:8px;background:#0b8a6b;color:#fff;border:0;cursor:pointer'>Copy</button>
          </div>
        </div>

      </main>

      <aside>
        <div class='card'>
          <strong>Important disclaimer</strong>
          <p class='muted' style='margin-top:8px'>This site offers educational resources and integrative guidance. It is not a medical diagnosis nor a guarantee of results. If you are experiencing a medical emergency, please call local emergency services immediately.</p>
        </div>

        <div class='card' style='margin-top:12px'>
          <strong>How we protect people</strong>
          <p class='muted' style='margin-top:8px'>Care plans are collaborative. Where medical tests or specialized care are needed, referrals are made to appropriate clinicians.</p>
        </div>
      </aside>
    </div>

    <footer>
      <div class='muted'>Questions? Call {{PHONE}} or <a href='mailto:{{EMAIL}}'>email</a>.</div>
    </footer>
  </div>

  <script>
    function generateCondAgenda(){
      const checked = Array.from(document.querySelectorAll('#condInventory input[name="area"]:checked')).map(i=>i.value);
      if(checked.length===0){document.getElementById('condOutput').textContent='No areas selected.';return}
      const out = [];
      out.push('Consult agenda (60 min):');
      out.push('- 0–10 min: Presenting concern and medical context');
      out.push('- 10–25 min: Primary focus — ' + checked[0]);
      if(checked.length>1) out.push('- 25–40 min: Secondary priorities — ' + checked.slice(1).join(', '));
      out.push('- 40–55 min: Practical steps and monitoring plan');
      out.push('- 55–60 min: Next actions and resources');
      out.push('\nFollow-up cadence:');
      out.push('- Brief check-in 1–2 weeks (15 min)');
      out.push('- Focused review 6 weeks (30–45 min)');
      document.getElementById('condOutput').textContent = out.join('\n');
    }
    function copyOut(id){
      const txt = document.getElementById(id).textContent;
      if(navigator.clipboard){navigator.clipboard.writeText(txt).then(()=>alert('Copied'))}else{alert('Copy not supported')}
    }
  </script>
</body>
</html>"} 
{"path":"approach.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Method & Practice — {{BUSINESS_NAME}}</title>
  <meta name='description' content='Our clinical ethos, cohort format, and how we translate evidence into everyday practices.'>
  <style>
    :root{--bg:#f7f8fb;--ink:#081230;--muted:#586174;--accent:#d86b5e}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial;margin:0;background:var(--bg);color:var(--ink)}
    .container{max-width:980px;margin:26px auto;padding:22px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{margin-left:10px;color:var(--muted);text-decoration:none}
    .lead{background:#fff;padding:18px;border-radius:12px;box-shadow:0 8px 28px rgba(6,10,16,0.03);margin-top:16px}
    .three{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:16px}
    .box{background:#fff;padding:14px;border-radius:12px}
    .muted{color:var(--muted)}
    .pattern{height:120px;border-radius:10px;margin-top:12px;background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='240' height='120' viewBox='0 0 240 120'><rect width='240' height='120' fill='none'/><g stroke='%23d86b5e' stroke-opacity='0.08' stroke-width='2'><path d='M0 30 C30 0 60 60 90 30 S150 0 180 30 S240 60 240 60'/></g></svg>");background-repeat:no-repeat;background-position:center}
    .widget{margin-top:16px}
    .output{background:#081230;color:#e8f6f1;padding:12px;border-radius:8px}
    button.cta{background:var(--accent);color:#fff;border:0;padding:10px 12px;border-radius:10px;cursor:pointer}
    footer{margin-top:18px;color:var(--muted)}
    @media(max-width:740px){.three{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <div class='container'>
    <header>
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <div class='muted'>A practical method for lasting adjustments</div>
      </div>
      <nav>
        <a href='index.html'>Home</a>
        <a href='services.html'>Programs</a>
        <a href='conditions.html'>Concerns</a>
        <a href='approach.html'>Method</a>
        <a href='book.html'>Reserve</a>
      </nav>
    </header>

    <section class='lead'>
      <h2 style='margin:0'>How we work — practice, measurement, and learning together</h2>
      <p class='muted' style='margin-top:8px'>We weave short experiments into daily life and review progress in small groups. Clinical judgment guides adaptations; participants keep practical records.</p>
      <div class='pattern'></div>
    </section>

    <div class='three'>
      <div class='box'>
        <h4 style='margin-top:0'>Listening first</h4>
        <p class='muted'>Stories matter: what you notice, when symptoms rise and fall, and how daily structure affects health.</p>
      </div>
      <div class='box'>
        <h4 style='margin-top:0'>Small experiments</h4>
        <p class='muted'>Micro-interventions you can try for 1–2 weeks to see what shifts. We build on measurable wins, not recipes.</p>
      </div>
      <div class='box'>
        <h4 style='margin-top:0'>Shared reflection</h4>
        <p class='muted'>Cohort meetings surface lessons and increase follow-through — a social engine for habit change.</p>
      </div>
    </div>

    <div class='box widget' style='margin-top:16px'>
      <h3 style='margin-top:0'>Session Planner</h3>
      <p class='muted'>Draft a compact agenda to bring to your next meeting. This helps clinicians and cohort members focus faster.</p>
      <div>
        <label class='muted'>Primary outcome</label>
        <input id='primary' placeholder='e.g., improve sleep efficiency' style='width:100%;padding:8px;border-radius:8px;border:1px solid #eceff3;margin-top:6px'/>
      </div>
      <div style='margin-top:8px;display:flex;gap:8px'>
        <input id='weeks' type='number' min='1' value='8' style='width:86px;padding:8px;border-radius:8px;border:1px solid #eceff3'/> <button class='cta' onclick='buildPlan()'>Build plan</button>
      </div>
      <pre class='output' id='approachPlan' style='margin-top:10px'>Your plan will appear here.</pre>
      <button onclick='copyPlan()' style='margin-top:8px;padding:8px 10px;border-radius:8px;background:#0b6a53;color:white;border:0;cursor:pointer'>Copy</button>
    </div>

    <div class='box' style='margin-top:16px'>
      <h3 style='margin-top:0'>Whole-person checklist</h3>
      <p class='muted'>Quickly mark the domains you'd like included in your plan; we generate a suggested check-in rhythm.</p>
      <form id='domainForm'>
        <label><input type='checkbox' name='d' value='Sleep'/> Sleep</label><br>
        <label><input type='checkbox' name='d' value='Nutrition'/> Nutrition</label><br>
        <label><input type='checkbox' name='d' value='Movement'/> Movement</label><br>
        <label><input type='checkbox' name='d' value='Stress'/> Stress</label><br>
      </form>
      <div style='margin-top:8px'>
        <button class='cta' onclick='composeAgenda()'>Compose agenda & cadence</button>
      </div>
      <pre class='output' id='approachAgenda' style='margin-top:10px'>Select domains to prepare an agenda.</pre>
      <button onclick='copyApproach("approachAgenda")' style='margin-top:8px;padding:8px 10px;border-radius:8px;background:#0b6a53;color:white;border:0;cursor:pointer'>Copy</button>
    </div>

    <footer>
      <div class='muted'>Educational support only. For urgent problems, seek immediate medical attention.</div>
    </footer>
  </div>

  <script>
    function buildPlan(){
      const primary = document.getElementById('primary').value || 'Priority goal';
      const weeks = parseInt(document.getElementById('weeks').value) || 6;
      const lines = [];
      lines.push('Plan overview — '+primary);
      lines.push('Duration: '+weeks+' weeks');
      lines.push('\nPhase 1 (weeks 1–2): observation & micro-changes');
      lines.push('- Track baseline for 7 days');
      lines.push('- Implement 1 small habit with simple metrics');
      lines.push('\nPhase 2 (weeks 3–'+Math.min(weeks,6)+') : consolidate and scale');
      lines.push('- Review data with clinician or cohort');
      lines.push('- Adjust practices and introduce a second micro-change');
      if(weeks>6) lines.push('\nPhase 3 (weeks 7–'+weeks+'): maintenance and integration');
      lines.push('- Plan for sustaining changes; peer check-ins or alumni review');
      document.getElementById('approachPlan').textContent = lines.join('\n');
    }
    function copyPlan(){
      const txt = document.getElementById('approachPlan').textContent;
      if(navigator.clipboard) navigator.clipboard.writeText(txt).then(()=>alert('Copied'));
    }
    function composeAgenda(){
      const checked = Array.from(document.querySelectorAll('#domainForm input[name="d"]:checked')).map(i=>i.value);
      if(checked.length===0){document.getElementById('approachAgenda').textContent='No domains selected.';return}
      const out = [];
      out.push('Agenda (60 min):');
      out.push('- Opening: goals and measures');
      out.push('- Focus: '+ checked[0]);
      if(checked.length>1) out.push('- Secondary review: '+checked.slice(1).join(', '));
      out.push('- Practical experiment to try this week');
      out.push('\nFollow-up cadence:');
      out.push('- 1–2 week micro-check (15 min)');
      out.push('- 6-week review (group or individual)');
      document.getElementById('approachAgenda').textContent = out.join('\n');
    }
    function copyApproach(id){
      const txt = document.getElementById(id).textContent;
      if(navigator.clipboard) navigator.clipboard.writeText(txt).then(()=>alert('Copied'));
    }
  </script>
</body>
